select ok((public.admin_transition_physical_pilot_commissioning_v1((select id from public.gps_devices where device_code='M26-FIXTURE'),'26000000-0000-0000-0000-000000000004','26000000-0000-0000-0000-000000000003',1,'26000000-0000-0000-0000-000000000008','commissioning','fixture_start','fixture_network',60)->>'replayed')::boolean,'exact transition replay returns frozen receipt');
