select lives_ok($$select public.service_record_physical_pilot_evidence_v1('26000000-0000-0000-0000-000000000012',(select id from public.physical_pilot_commissioning where gps_device_id=(select id from public.gps_devices where device_code='M26-FIXTURE')),2,'26000000-0000-0000-0000-000000000004','26000000-0000-0000-0000-000000000003',repeat('b',40),'fixture_workflow',(select id from public.gps_devices where device_code='M26-FIXTURE'),public.m22_safe_digest((select id::text from public.gps_devices where device_code='M26-FIXTURE')),(select id from public.gps_device_lifecycle_events where gps_device_id=(select id from public.gps_devices where device_code='M26-FIXTURE') and event_type='installed'),(select id from public.gps_device_vehicle_links where gps_device_id=(select id from public.gps_devices where device_code='M26-FIXTURE') and effective_until is null),'26000000-0000-0000-0000-000000000006','26000000-0000-0000-0000-000000000009','physical',(select observation_started_at from public.physical_pilot_evidence_receipts where id='26000000-0000-0000-0000-000000000012'),(select observation_ended_at from public.physical_pilot_evidence_receipts where id='26000000-0000-0000-0000-000000000012'),10,true,true,'passed','passed',true,true,'pass','{}',repeat('d',64))$$,'exact evidence response-loss replay returns frozen receipt');
